csui.define('dctmw/utils/authenticators/auth.storage',[
  'nuc/lib/underscore',
  'dctmw/utils/utils',
  'dctmw/utils/constants'
], function (_, utils, constants) {
  'use strict';

  /*
   * This utility helps in tracking various authentication related data.
   * There are 2 stores to track the same:
   *   1. AUTH_DATA - localStorage - data stored with key as AUTH_TABS
   *      It stores list of all open tabs along with the combination of Repository-Application-NetworkLocation for each.
   *      This store also might have other data like authenticated repo list which might be added by various authenticators.
   *   2. AUTH_TABS - sessionStorage
   *      It just stores the current browser tab's unique identifier. This same ID can be used to lookup other auth
   *      data in AUTH_DATA -> AUTH_TABS store.
   */

  var
    AUTH_TABS = 'authTabs',
    TAB_ID = 'tabId',
    authData = utils.getLocalStore(constants.StorageKey.AUTH_DATA),
    sessionData = utils.getSessionStore(constants.StorageKey.AUTH_TABS),
    repoSessionData = utils.getSessionStore(constants.StorageKey.REPO_DATA);

  return {

    /**
     * Returns object of auth data for all tabs with tabId as key for each.
     * e.g.
     * {
     *   tab1: {
     *     repository: 'repoA',
     *     networkLocation: 'london'
     *   },
     *   tab2: {
     *     repository: 'repoB',
     *     application: 'finance',
     *     networkLocation: 'newyork'
     *   }
     * }
     */
    getAllTabsData: function () {
      return authData.get(AUTH_TABS) || {};
    },

    /**
     * Sets auth data for all tabs with tabId as key for each.
     */
    setAllTabsData: function (data) {
      return authData.set(AUTH_TABS, data);
    },

    /**
     * Returns auth data for the current tab.
     * e.g.
     * {
     *   repository: 'repoA',
     *   application: 'finance',
     *   networkLocation: 'newyork'
     * }
     */
    getCurrTabData: function () {
      var currTabId = this.getCurrTabId(),
        tabsData = this.getAllTabsData();
      return tabsData[currTabId] || {};
    },

    /**
     * Sets the auth data for the current tab.
     */
    setCurrTabData: function (data) {
      var currTabId = this.getCurrTabId(),
        tabsData = this.getAllTabsData();
      tabsData[currTabId] = data;
      authData.set(AUTH_TABS, tabsData);
    },

    /**
     * Removes the auth data for the current tab.
     */
    removeCurrTabData: function () {
      var currTabId = this.getCurrTabId(),
        tabsData = this.getAllTabsData();
      delete tabsData[currTabId];
      authData.set(AUTH_TABS, tabsData);
    },

    /**
     * Gets the current tab Id.
     */
    getCurrTabId: function () {
      var tabId = sessionData.get(TAB_ID);
      if (!tabId) {
        tabId = new Date().getTime() + '-' + Math.floor(Math.random() * 1000);
        this._setCurrTabId(tabId);
      }
      return tabId;
    },

    /**
     * Sets the current tab Id in session store.
     */
    _setCurrTabId: function (tabId) {
      sessionData.set(TAB_ID, tabId);
    },

    setAuthRepoData: function (repo, data) {
      repoSessionData.set(repo, data);
    },

    getAuthRepoData: function (repo) {
      var repoDataValue = repoSessionData.get(repo) || {};
      return repoDataValue;
    },

    removeAuthRepoData: function (repo) {
      repoSessionData.remove(repo);
    }

  };

});


