  'nuc/utils/authenticators/authenticators',
  'nuc/contexts/context',
  'nuc/contexts/factories/connector',
  'dctmw/models/product.info',
  'dctmw/models/repositories',
  'dctmw/models/session/current.user',
  'dctmw/models/session/current.user.preference',
  'dctmw/utils/constants',
  'dctmw/utils/rest.resources',
  'dctmw/utils/rest.linkrels',
  'dctmw/utils/utils',
  'dctmw/utils/geolocation.utils',
