csui.define('dctmw/pages/error/start.page.error.view',[
  'nuc/lib/underscore',
  'nuc/lib/jquery',
  'nuc/lib/marionette',
  'nuc/utils/base',
  'dctmw/utils/constants',
  'dctmw/utils/client.location',
  'dctmw/utils/authenticators/session',
  'i18n!dctmw/pages/error/impl/nls/lang',
  'hbs!dctmw/pages/error/impl/start.page.error',
  'hbs!dctmw/pages/error/impl/location.page.error',
  'css!dctmw/pages/error/impl/start.page.error'
], function (_, $, Marionette, base, constants, clientLocation, Session, lang, Template, LocationErrorTemplate) {

  var StartPageErrorView = Marionette.ItemView.extend({
    className: 'start-page-error',

    template: Template,

    ui: {
      errorMessageWrapper: '.error-message-wrapper',
      signOutButton: '.buttons-container .signout-user',
      pageReloadButton: '.buttons-container .page-reload'
    },

    events: {
      'click @ui.signOutButton': 'onSignOutClick',
      'keydown @ui.signOutButton': 'onSignOutKeyDown',
      'click @ui.pageReloadButton': 'onPageReloadClick',
      'keydown @ui.pageReloadButton': 'onPageReloadKeyDown',
    },

    templateHelpers: function () {
      return {
        signOut: lang.signOutLabel,
        reloadLabel: lang.reloadLabel,
        errorMsgs: this.errMsgs,
        showHeader: !this.options.embedMode,
        showSignout: this.session.isActive() || this.options.licenseFailed,
        showReload: (this.options.showPageReloadButton === true)
      }
    },

    constructor: function StartPageErrorView(options) {

      options || (options = {});

      this.options = options;
      this.session = Session.get();
      this.context = this.session.getContext();

      var errMsgs = (typeof this.options.errorMsg === 'string') ? this.options.errorMsg : lang.appLoadingError;

      // if error is because of licensing
      if (this.options.responseJSON) {
        if (this.options.responseJSON.status === 403
            && ( this.options.responseJSON.code.includes("E_LICENCE")
              || this.options.responseJSON.code.includes("E_LICENSE")
              || this.options.responseJSON.code.includes("DM_LICENSE")
              || this.options.responseJSON.code.includes("DM_LICENCE")
            )) {
          errMsgs = this.options.responseJSON.message;
          if (!this.options.embedMode) {
            this.options.licenseFailed = true;
          }
        }
      }

      if(options.locationError){
        this.template = LocationErrorTemplate;
      }

      errMsgs = errMsgs.split("\n");
      this.errMsgs = errMsgs;

      Marionette.View.prototype.constructor.call(this, options);
    },

    initialize: function() {
    },

    onSignOutClick: function () {
      csui.require([
        'dctmw/commands/sign.out'
      ], function(CmdSignOut){
        let cmdSignout = new CmdSignOut();
        cmdSignout.execute({
          context: this.context,
          licenseFailed: this.options.licenseFailed
        });
      }.bind(this));
    },

    getValueFromStorage: function (key, storage) {
      var appContext = window.location.pathname.split('/')[1],
          storeKey = 'D2:' + appContext + ':' + key;
      return storage.getItem(storeKey);
    },

    signOut: function (context) {
      var dfd = $.Deferred();
      csui.require([
        'nuc/contexts/factories/connector'
      ], function () {
        var ConnectorFactory = arguments[0];
        var connector = context.getObject(ConnectorFactory);
        var authData = {};
        authData = JSON.parse(this.getValueFromStorage('authData', window.localStorage));
        $.ajax(connector.extendAjaxOptions({
          url: connector.connection.url + '/repositories/' + authData.repository + '/logout',
          success: function () {
            var urlParams = {};
            urlParams['nextUrl'] = encodeURIComponent(location.hash);
            urlParams[constants.AppUrlParams.LOGGED_OUT] = 'true';

            connector.authenticator.unauthenticate({reason: 'logged-out'});
            clientLocation.navigate('signin', {trigger: true, hashParams: urlParams});
            dfd.resolve();
          },
          error: dfd.reject
        }))
      }.bind(this), dfd.reject);
      return dfd.promise();
    },

    onSignOutKeyDown: function (event) {
      if(event.which === 13 || event.which === 32){
        this.onSignOutClick();
      }
    },

    onPageReloadClick: function(event) {
      if(this.isPageReloading !== true) {
        event && event.stopPropagation();
        this.isPageReloading = true;
        clientLocation.reload();
      }
    },

    onPageReloadKeyDown: function(event) {
      if(event.which === 13 || event.which === 32){
        this.onPageReloadClick(event);
      }
    }
  });

  return StartPageErrorView;

});


csui.define('dctmw/controls/signin/repository.view',[
  'nuc/lib/marionette'
], function (Marionette) {
  'use strict';

  var RepositoryItemView = Marionette.ItemView.extend({

    tagName: 'option',
    className: 'signin-option',
    template: false,

    onRender: function () {
      var name = this.model.get('name'),
        docbaseDescription = this.model.get('description');
      if(this.model.has('repository')) {
        const repo = this.model.get('repository');
        name = repo.repositoryName;
        docbaseDescription = repo.docbaseDescription;
      }
      this.$el.text(docbaseDescription || name);
      this.$el.val(name);
    }
  });

  return RepositoryItemView;
});

csui.define('dctmw/controls/signin/repository.list.view',[
  'nuc/lib/marionette',
  'dctmw/controls/signin/repository.view'
], function (Marionette, RepositoryItemView) {
  'use strict';

  var RepositoryListView = Marionette.CollectionView.extend({
    tagName: 'select',
    tabindex: '0',
    childView: RepositoryItemView,
    className: 'repository-select',
    attributes: { "aria-label": "Select a repository", "required": "required" },

    getRepositoryById: function (id) {
      var repository;
      this.collection.models.some(function (model) {
        model = model.has('repository') ? model.get('repository') : model;
        if (model.id === id) {
          repository = model;
          return true;
        }
      });
      return repository;
    },

    // Returns an index between 1 and the collection length if id is found, 0 if not found
    getRepositoryIndex: function (id) {
      var result = 0;
      var index = 1;
      this.collection.models.some(function (model) {
        var modelRepo = model.get('repository');
        if (modelRepo.id === id) {
          result = index;
          return true;
        }
        index += 1;
      });
      return result;
    }
  });

  return RepositoryListView;
});


