csui.define('dctmw/utils/load-extensions/ext.utils',[
  'nuc/lib/underscore'
], function(_){
  'use strict';

  function parseExtensions(extraTileDefinitions) {
    var extObjects = [];

    if (extraTileDefinitions) {
      _.each(extraTileDefinitions, function(extGr){
        var grNS = extGr._srcNS,
          newGr = _.map(extGr, function(obj){
            if(_.isObject(obj)) {
              return _.extend(obj, {_srcNS: grNS})
            }
            return obj;
          });
        extObjects = extObjects.concat(newGr);
      });
    }

    return extObjects;
  }

  return {
    parseExtensions: parseExtensions
  };
});

