csui.define('dctmw/utils/startup',[
  'require',
  'nuc/lib/jquery',
  'nuc/lib/underscore',
  'nuc/contexts/factories/connector',
  'nuc/utils/url',
  'dctmw/models/formats',
  'dctmw/utils/authenticators/session',
  'dctmw/utils/rest.linkrels',
  'dctmw/utils/rest.resources',
  'dctmw/utils/utils',
  'css!dctmw/controls/controls'
], function(require, $, _, ConnectorFactory, Url, FormatCollection, Session, RestLinkrels, RestResources, utils){
  'use strict';

  return {
    beforeStartup: function(options={}) {
      _.defaults(options, {context: Session.get().getContext()});

      return this.fetchStartupData(options)
        .then(()=>{
          const dfdInner = $.Deferred();
          csui.require(['dctmw/utils/startup.hooks'], function(startupHooks){
            startupHooks.beforeStartup(options)
              .done(dfdInner.resolve).fail(dfdInner.reject);
          }, dfdInner.reject);
          return dfdInner.promise();
        });
    },

    afterStartup: function(options={}) {
      const dfd = $.Deferred();

      _.defaults(options, {context: Session.get().getContext()});

      csui.require(['dctmw/utils/startup.hooks'], function(startupHooks){
        startupHooks.afterStartup(options)
          .done(dfd.resolve).fail(dfd.reject);
      }, dfd.reject);

      return dfd.promise();
    },

    fetchStartupData: function(options) {
      const dfd = $.Deferred(),
        currRepoLinks = RestResources.getCurrentRepository().get('links'),
        batchPayload = [
          {
            id: 'formats',
            request: {
              method: 'GET',
              uri: Url.appendQuery(RestLinkrels.getLink(currRepoLinks, RestLinkrels.FORMATS), Url.combineQueryString({
                'inline': true,
                'items-per-page': 100000
              }))
            }
          }
        ];

      utils.makeBatchAjaxCall({
        connector: options.context.getObject(ConnectorFactory),
        operations: batchPayload
      }).done((successful, failed)=>{
        if (failed && failed.length > 0) {
          dfd.reject();
          return;
        }

        _.each(successful, (operation)=>{
          const data = operation.output;
          switch(operation.id) {
            case 'formats':
              const formats = (data.entries || []).map(function (entry) { //eslint-disable-line no-case-declarations
                return _.extend(_.pick(entry.content, 'is-default'), _.pick(entry.content.properties, 'name', 'r_object_id', 'mime_type', 'dos_extension', 'description', 'is_hidden')); /* eslint-dsable*/
              });
              RestResources.setFormats(new FormatCollection(formats));
              break;
          }
        });

        dfd.resolve();
      })
        .fail(dfd.reject);

      return dfd.promise();
    }
  };
});

csui.define('dctmw/utils/startup.hooks',[
  'module',
  'require',
  'nuc/lib/underscore',
  'nuc/lib/jquery',
  'nuc/utils/log',
  'dctmw/models/module.collection',
  'dctmw/utils/utils'
], function (module, require, _, $, log, ServerModuleCollection, utils) {
  'use strict';

  const logger = log(module.id);
  const pluginModuleModels = new ServerModuleCollection().getPluginModules();

  function createChainedExecutor(relativeModulePath, functionName) {
    if (!relativeModulePath.startsWith('/')) {
      relativeModulePath = ('/' + relativeModulePath);
    }

    return function () {
      const args = arguments,
        modulePaths = pluginModuleModels.map(function (model) {
          return model.get('id') + relativeModulePath;
        });

      return _.reduce(modulePaths, function (promise, moduleId) {
        const dfd = $.Deferred();
        promise.done(function () {
          const prevArgs = Array.prototype.slice.call(arguments);
          logger.debug(`Loading : ${moduleId}`) && console.log(logger.last);
          require([moduleId], function (module) {
            logger.debug(`Loaded : ${moduleId}`) && console.log(logger.last);
            if (module && _.isFunction(module[functionName])) {
              const retVal = module[functionName].apply(module, args);
              if (utils.isJqueryPromise(retVal)) {
                logger.debug(`Async '${functionName}()' in module ${moduleId}`) && console.log(logger.last);
                retVal.done(function(){
                  const localArgs = Array.prototype.slice.call(arguments);
                  dfd.resolve.apply(dfd, [...prevArgs, ...localArgs]);
                }).fail(e => {
                  logger.error(`Error "${e instanceof Error ? e.message : e}" in executing '${functionName}()' of module ${moduleId}`) && console.error(logger.last);
                  dfd.reject.apply(dfd, [...prevArgs, e]);
                });
              } else {
                logger.debug(`Sync '${functionName}()' in module ${moduleId}`) && console.log(logger.last);
                dfd.resolve.apply(dfd, [...prevArgs, retVal]);
              }
            } else {
              logger.warn(`No '${functionName}()' in module ${moduleId}`) && console.warn(logger.last);
              dfd.resolve.apply(dfd, prevArgs);
            }
          }, function(e){
            logger.warn(`Failed to load : ${moduleId} due to ${e.message}`) && console.warn(logger.last);
            if(e.requireType === 'scripterror' && e.requireModules[0] === moduleId) {
              logger.warn(`Continuing '${functionName}()' despite of module load error`) && console.warn(logger.last);
              dfd.resolve.apply(dfd, prevArgs);
            } else {
              logger.error(`Halting '${functionName}()' due to module load error`) && console.error(logger.last);
              dfd.reject.apply(dfd, [...prevArgs, e]);
            }
          });
        }).fail(dfd.reject);
        
        return dfd.promise();
      }, $.Deferred().resolve().promise());
    };
  }
  
  return {
    beforeStartup: createChainedExecutor('utils/startup', 'beforeStartup'),
    afterStartup: createChainedExecutor('utils/startup', 'afterStartup')
  };
});


