csui.define('dctmw/utils/overrides',[
  'module',
  'require',
  'nuc/lib/jquery'
], function(module, require, $){
  
  const config = Object.values(module.config());
  const dfd = $.Deferred();
  
  require(config, ()=>{
    dfd.resolve();
  }, dfd.reject);
  
  return dfd.promise();
});


