csui.define('dctmw/commands/sign.out',[
  'require',
  'nuc/lib/underscore',
  'nuc/lib/jquery',
  'nuc/lib/backbone',
  'nuc/utils/url',
  'dctmw/utils/rest.resources',
  'dctmw/utils/rest.linkrels',
  'dctmw/utils/utils',
  'dctmw/utils/constants',
  'dctmw/utils/client.location',
  'i18n!csui/utils/commands/nls/localized.strings'
], function (require, _, $, Backbone, Url, RestResources, RestLinkrels, utils, constants, clientLocation, lang) {
  'use strict';

  var ConnectorFactory;

  return Backbone.Model.extend({
    idAttribute: 'signature',

    defaults: {
      signature: 'SignOut',
      command_key: 'SignOut',
      name: lang.SignOutCommandName
    },

    getCommandKey: function () {
      var commandKey = this.get('command_key');
      return commandKey ? Array.isArray(commandKey) ? commandKey : [commandKey] : [];
    },

    enabled: function () {
      /*var action = RestResources.getCurrentUser().get('MenuActions').get(this.get('signature'));
      return !!action;*/
      return true;
    },

    execute: function (status, options) {
      var deferred = $.Deferred(),
          context = status.context || options && options.context,
          licenseFailed = status.licenseFailed,
          self = this;
      csui.require([
        'csui/utils/contexts/factories/connector',
        'csui/pages/start/impl/perspective.router'
      ], function () {
        ConnectorFactory = arguments[0];
        self._signOut(context, licenseFailed)
            .done(deferred.resolve)
            .fail(deferred.reject);
      }, deferred.reject);
      return deferred.promise();
    },

    _signOut: function (context, licenseFailed) {
      var connector = context.getObject(ConnectorFactory),
          skippedSSO = clientLocation.getQueryParams()['skipsso'] === 'true';

      //REST-API does not return logoff linkrel in the response, when /repo request carries OTDS bearer token and it would take
      //another /repo call to get just that linkrel. However, it's not the case for basic-ct login.
      //so to make it work for both cases, until REST-API fixes their implementation, we form the logout URL on our own - JD
      var repoLogoutUrl = this.getRepoLogoutUrl(connector, licenseFailed);

      return $.ajax(connector.extendAjaxOptions({
        url: repoLogoutUrl
      })).done(function (/*response*/) {
        if(licenseFailed !== true) {
          connector.authenticator.unauthenticate({reason: 'logged-out'});
          utils.getLocalStore(constants.StorageKey.MOBILE).destroy();
        }
        var redirectUrl = this.getRedirectUrl(connector);
        var otdsLogoutUrl = this.getOtdsLogoutUrl(licenseFailed);
        if (otdsLogoutUrl && !skippedSSO) {
          if (licenseFailed && redirectUrl.startsWith(location.origin)) {
            var signInPageUrl = connector.authenticator.getSigninUrl(), hashParams = {};
            hashParams['nextUrl'] = encodeURIComponent(location.hash);
            hashParams[constants.AppUrlParams.LOGGED_OUT] = 'true';
            redirectUrl = location.origin + location.pathname + location.search + Url.appendQuery(signInPageUrl, Url.combineQueryString(hashParams['nextUrl']));
          }
          redirectUrl = otdsLogoutUrl + '&redirect_uri=' + encodeURIComponent(redirectUrl);
        }
        utils.openUrlInWindow(redirectUrl);
      }.bind(this));
    },

    getRepoLogoutUrl: function (connector, licenseFailed) {
      // if license error then pick from local storage: last selected login item
      if(licenseFailed === true) {
        var lastSelItemsStorage = utils.getLocalStore(constants.StorageKey.LAST_SELECTED_LOGIN_ITEMS),
            repository = lastSelItemsStorage.get(constants.LastSelectedLoginItems.REPOSITORY);
        if (repository) {
          return connector.connection.url + '/repositories/' + repository + '/logout'
        }
      } else {
        return Url.combine(RestLinkrels.getLink(RestResources.getCurrentRepository().get('links'), RestLinkrels.SELF), 'logout'); //RestLinkrels.getLink(RestResources.getCurrentRepository().get('links'), RestLinkrels.LOGOFF)
      }
    },


    getOtdsLogoutUrl: function (licenseFailed) {
      if(licenseFailed === true) {
        return RestResources.getProductInfo().get('otds-logout');
      } else {
        return RestLinkrels.getLink(RestResources.getCurrentRepository().get('links'), RestLinkrels.OTDS_LOGOUT);
      }
    },

    getRedirectUrl: function (connector) {
      //Fetch the logout redirect URL if existing
      var redirectUrl = RestResources.getD2Options().logout_redirect_url;
      if (redirectUrl) {
        return redirectUrl;
      }

      var signInPageUrl = connector.authenticator.getSigninUrl(),
          hashParams = {};

      hashParams['nextUrl'] = encodeURIComponent(location.hash);
      hashParams[constants.AppUrlParams.LOGGED_OUT] = 'true';
      /*if(urlParams["_ssoauthfail_"]){
        delete urlParams["_ssoauthfail_"];
      }*/

      return location.origin + location.pathname + location.search + Url.appendQuery(signInPageUrl, Url.combineQueryString(hashParams));
    }

  });

});


